export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

/** Raised when a milestone is in the wrong state for the requested change. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: MilestoneStateReason, message?: string) {
    super(message ?? `Milestone state conflict: ${reason}`);
    this.name = "MilestoneStateError";
  }
}

/** Case- and whitespace-insensitive key two milestone names are compared by. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}
