/**
 * Project milestones: creation, naming, closing (which re-homes open issues) and progress.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { actorEnvelope, projectResource, requireFound } from "./_support";
// Importing the hub is what attaches the fan-out for `milestone.closed`.
import "./notification-service";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

async function loadProject(orgId: OrgId, projectId: ProjectId): Promise<Project> {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

/** Loads a milestone and its project, then checks `project:update` and liveness. */
async function loadForWrite(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ milestone: Milestone; project: Project }> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return { milestone, project };
}

async function assertNameFree(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<void> {
  const key = milestoneNameKey(name);
  const all = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  if (all.some((m) => m.id !== exceptId && milestoneNameKey(m.name) === key)) {
    throw new MilestoneStateError("name_taken", `Milestone name "${name}" is taken`);
  }
}

async function assertRoomForOpen(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError(
      "too_many_open",
      `A project holds at most ${MAX_OPEN_MILESTONES_PER_PROJECT} open milestones`,
    );
  }
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await loadProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  await assertNameFree(input.orgId, project.id, input.name, null);
  await assertRoomForOpen(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name: input.name,
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const { milestone } = await loadForWrite(actor, input.orgId, input.milestoneId);

  if (input.name !== undefined) {
    await assertNameFree(
      input.orgId,
      milestone.projectId,
      input.name,
      milestone.id,
    );
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    name: input.name,
    targetDate: input.targetDate,
  });
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const { milestone } = await loadForWrite(actor, input.orgId, input.milestoneId);
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");

  const targetId = input.moveOpenIssuesTo;
  if (targetId !== null) {
    if (targetId === milestone.id) {
      throw new NotFoundErrorFor(targetId);
    }
    const target = await milestoneRepo.findMilestoneById(input.orgId, targetId);
    if (target === null || target.projectId !== milestone.projectId) {
      throw new NotFoundErrorFor(targetId);
    }
    if (target.closedAt !== null) throw new MilestoneStateError("closed");
  }

  const result = await milestoneRepo.closeMilestone(
    input.orgId,
    milestone.id,
    targetId,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds: result.movedIssueIds,
  });

  return result;
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const { milestone } = await loadForWrite(actor, orgId, milestoneId);
  if (milestone.closedAt === null) throw new MilestoneStateError("already_open");
  await assertRoomForOpen(orgId, milestone.projectId);

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestone.id);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

function withProgress(
  milestones: readonly Milestone[],
  progress: Awaited<ReturnType<typeof milestoneRepo.getProgressByMilestone>>,
  now: number,
): readonly MilestoneWithProgress[] {
  return milestones.map((milestone) => {
    const p = progress.get(milestone.id) ?? { total: 0, open: 0, closed: 0 };
    const overdue =
      milestone.closedAt === null &&
      milestone.targetDate !== null &&
      Date.parse(milestone.targetDate) < now &&
      p.open > 0;
    return { milestone, progress: p, overdue };
  });
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const now = Date.now();
  const all = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  const progress = await milestoneRepo.getProgressByMilestone(
    orgId,
    all.map((m) => m.id),
  );

  const rank = (m: Milestone): number =>
    m.targetDate === null ? Number.POSITIVE_INFINITY : Date.parse(m.targetDate);

  const sorted = [...withProgress(all, progress, now)].sort((a, b) => {
    const ca = a.milestone.closedAt === null ? 0 : 1;
    const cb = b.milestone.closedAt === null ? 0 : 1;
    if (ca !== cb) return ca - cb;
    const ra = rank(a.milestone);
    const rb = rank(b.milestone);
    if (ra !== rb) return ra < rb ? -1 : 1;
    // `all` is already oldest-first and Array#sort is stable.
    return 0;
  });
  return sorted;
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));

  const progress = await milestoneRepo.getProgressByMilestone(orgId, [
    milestone.id,
  ]);
  return withProgress([milestone], progress, Date.now())[0]!;
}
