/** Puts an issue into an open milestone of its project, or takes it out. */
export async function setIssueMilestone(
  actor: Actor,
  input: SetIssueMilestoneInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
